CREATE OR REPLACE FUNCTION calculate_market_risk(
    p_daily_flow bigint,
    p_escrow_rate numeric,
    p_inter_score numeric,
    p_vendor_count integer,
    p_market_span integer
) RETURNS numeric AS $func$
BEGIN
    RETURN ROUND(CAST((CAST(p_daily_flow AS numeric) / 1000.0 + (p_escrow_rate * 0.2) + (p_inter_score * 0.3) + (CAST(p_vendor_count AS numeric) * 0.1) - CAST(p_market_span AS numeric) / 100.0) AS numeric), 2);
END;
$func$ LANGUAGE plpgsql;
